<?php $plural=$domain==='career'?'careers':'bursaries';?><div class="d-flex justify-content-between mb-4"><h1>Manage <?=e(ucfirst($plural))?></h1><a class="btn btn-primary" href="<?=e(url('/admin/'.$plural.'/create'))?>">New draft</a></div><?php if($create):?><form method="post" action="<?=e(url('/admin/'.$plural))?>" class="card card-body mb-4"><?=csrf_field()?><div class="row g-3"><div class="col-md-6"><label class="form-label">Title</label><input name="title" class="form-control" required></div><?php if($domain==='career'):?><div class="col-md-6"><label class="form-label">Organisation</label><input name="organisation" class="form-control" required></div><div class="col-md-4"><label class="form-label">Location</label><input name="location" class="form-control"></div><div class="col-md-4"><label class="form-label">Employment type</label><input name="employment_type" class="form-control" required></div><div class="col-md-4"><label class="form-label">Work arrangement</label><input name="work_arrangement" class="form-control"></div><input type="hidden" name="province_id" value="0"><input type="hidden" name="profession_id" value="0"><div class="col-12"><label class="form-label">Summary</label><textarea name="summary" class="form-control" required></textarea></div><div class="col-12"><label class="form-label">Description</label><textarea name="description" class="form-control" required></textarea></div><div class="col-12"><label class="form-label">Requirements</label><textarea name="requirements" class="form-control" required></textarea></div><input type="hidden" name="application_instructions"><input type="hidden" name="external_url"><?php else:?><div class="col-md-6"><label class="form-label">Provider</label><input name="provider" class="form-control" required></div><div class="col-md-6"><label class="form-label">Field of study</label><input name="field_of_study" class="form-control" required></div><div class="col-md-6"><label class="form-label">Study level</label><input name="study_level" class="form-control" required></div><div class="col-12"><label class="form-label">Description</label><textarea name="description" class="form-control" required></textarea></div><div class="col-12"><label class="form-label">Eligibility criteria</label><textarea name="eligibility_criteria" class="form-control" required></textarea></div><div class="col-12"><label class="form-label">Benefits</label><textarea name="benefits" class="form-control" required></textarea></div><div class="col-md-6"><label class="form-label">Opening date</label><input type="date" name="opening_date" class="form-control" required></div><?php endif;?><div class="col-md-6"><label class="form-label">Closing date</label><input type="date" name="closing_date" class="form-control" required></div></div><button class="btn btn-primary mt-3">Save draft</button></form><?php endif;?><a href="<?=e(url('/admin/'.$plural.'/applications'))?>">Open application review queue</a><div class="table-responsive mt-3"><table class="table"><thead><tr><th>Reference</th><th>Title</th><th>Status</th><th>Closing</th><th>Actions</th></tr></thead><tbody><?php foreach($opportunities as $o):?><tr><td><?=e($o['opportunity_reference'])?></td><td><?=e($o['title'])?></td><td><?=e($o['status'])?></td><td><?=e($o['closing_date'])?></td><td><?php $next=['draft'=>'published','published'=>'closed','closed'=>'archived'][$o['status']]??null;if($next):?><form method="post" action="<?=e(url('/admin/'.$plural.'/'.$o['opportunity_reference'].'/status/'.$next))?>" onsubmit="return confirm('Move this opportunity to <?=e($next)?>?')"><?=csrf_field()?><button class="btn btn-sm btn-outline-primary"><?=e(ucfirst($next))?></button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div>
